    /* sdd-asis-lifecycle:begin onCloseCalendar — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (scwin.openCalendarObj === scwin.form.basDd[0] || scwin.openCalendarObj === scwin.form.basDd[1]) {
        return;
    }
    scwin.openCalendarObj.value = scwin.openCalendarObj.value.substring(0, 6);
    scwin.paramCalendarObj.value = scwin.openCalendarObj.value;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.vailidationLn
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.vailidationLn = async function () {
    /* sdd-asis-lifecycle:begin fn_Vailidation_ln — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (i = 0; i < 3; i++) {
        const arrObj = $c.util.getComponent('slc_audtOpinTpCd');
        if (arrObj[i].value === '') {
            await $c.win.alert('해당사항을 선택하셔야 합니다.');
            console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
    /* sdd-asis-lifecycle:begin fn_Register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await scwin.isPossibleSave()) {
        return;
    }
    if (!await scwin.vailidationLn()) {
        return;
    }
    const CheckArrDateArrVar1 = new Array('acntclsYymm');
    const CheckArrDateArrVar2 = new Array('basDd');
    if (!fn_IsValidArrDate(scwin.form, CheckArrDateArrVar1, 6)) {
        return;
    }
    if (!fn_IsValidArrDate(scwin.form, CheckArrDateArrVar2, 6)) {
        return;
    }
    if (!fn_IsValidArr(scwin.form, CheckArrVar, CheckArrVarAlt)) {
        return;
    }
    if (!$c.lc.fn_isProcess('I')) {
        return;
    }
    scwin.rmCommaValueAll();
    scwin.form.action = '/list/elw.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'registerElw');
    await scwin.tx_fn_Register();
    /* sdd-asis-lifecycle:end */
};


